/* Refresh Season Hub tabs after GitHub Pages publishes a new repository revision.
 * The same-origin revision endpoint is generated by GitHub Pages/Jekyll.
 * A GitHub API fallback supports static Pages deployments without Jekyll.
 */
(() => {
  "use strict";
  const STORAGE_KEY = "tarkov-site:last-deploy-revision";
  const PARAM = "_site_rev";
  const POLL_MS = 180000;
  const ENDPOINT = "/tarkov/build-revision.txt";
  const API = "https://api.github.com/repos/whizdohan/whizdohan.github.io/commits/main";
  const RE_SHA = /^[0-9a-f]{40}$/i;
  let checking = false;
  let refreshing = false;

  const readStored = () => { try { return sessionStorage.getItem(STORAGE_KEY); } catch { return null; } };
  const store = revision => { try { sessionStorage.setItem(STORAGE_KEY, revision); } catch {} };

  async function publishedRevision() {
    const url = new URL(ENDPOINT, location.origin);
    url.searchParams.set("check", String(Date.now()));
    const result = await fetch(url, { cache: "no-store" });
    if (result.ok) {
      const revision = (await result.text()).trim();
      if (RE_SHA.test(revision)) return revision.toLowerCase();
    }
    // Jekyll metadata can be unavailable for workflows that publish raw files.
    // Fall back to the public commit metadata without using browser caches.
    const fallback = await fetch(API, {
      cache: "no-store",
      headers: { Accept: "application/vnd.github+json" }
    });
    if (!fallback.ok) throw new Error("Revision lookup unavailable");
    const data = await fallback.json();
    if (!RE_SHA.test(data.sha || "")) throw new Error("Invalid revision");
    return data.sha.toLowerCase();
  }

  async function checkForUpdates() {
    if (checking || refreshing || document.visibilityState === "hidden") return;
    checking = true;
    try {
      const revision = await publishedRevision();
      const previous = readStored();
      if (!previous) { store(revision); return; }
      if (previous === revision) return;
      store(revision);
      refreshing = true;
      const url = new URL(location.href);
      url.searchParams.set(PARAM, revision.slice(0, 12));
      // A new URL forces a fresh HTML navigation without touching user progress in localStorage.
      location.replace(url.href);
    } catch (error) {
      // Offline, unsupported builds, and rate limits should never interrupt the page.
      console.debug("Site update check skipped:", error);
    } finally {
      checking = false;
    }
  }

  function versionLocalImages() {
    const revision = new URL(location.href).searchParams.get(PARAM);
    if (!revision || !/^[0-9a-f]{12}$/i.test(revision)) return;
    const update = image => {
      if (!(image instanceof HTMLImageElement)) return;
      const value = image.getAttribute("src");
      if (!value || value.startsWith("data:") || value.startsWith("blob:")) return;
      let url;
      try { url = new URL(value, location.href); } catch { return; }
      if (url.origin !== location.origin) return;
      if (url.searchParams.get(PARAM) === revision) return;
      url.searchParams.set(PARAM, revision);
      image.src = url.href;
    };
    document.querySelectorAll("img[src]").forEach(update);
    const observer = new MutationObserver(mutations => {
      for (const mutation of mutations) {
        if (mutation.type === "attributes") update(mutation.target);
        else for (const node of mutation.addedNodes) {
          if (node.nodeType !== Node.ELEMENT_NODE) continue;
          if (node.matches("img[src]")) update(node);
          node.querySelectorAll?.("img[src]").forEach(update);
        }
      }
    });
    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["src"]
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", versionLocalImages, { once: true });
  } else versionLocalImages();
  window.addEventListener("pageshow", checkForUpdates);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") checkForUpdates();
  });
  setInterval(checkForUpdates, POLL_MS);
})();
